// Builds the static Business Con × Krillion site into dist/ (GitHub Pages ready).
// Pixel art and fonts are generated by `npm run build` and already committed
// under public/assets, so this step needs no network and no dependencies.
import { cp, mkdir, rm, writeFile } from 'node:fs/promises';
import { campaignPage } from '../src/campaign-page.mjs';
import { QUESTIONS } from '../public/campaign.config.mjs';

const out = 'dist';
await rm(out, { recursive: true, force: true });
await mkdir(out, { recursive: true });
const files = ['app.mjs', 'campaign.config.mjs', 'campaign.css', 'local-api.mjs', 'ocean.mjs', 'presentation.mjs', 'rules.mjs', 'seascape.mjs', 'sound.mjs', 'style.css'];
for (const file of files) await cp('public/' + file, `${out}/${file}`);
await cp('public/assets', `${out}/assets`, { recursive: true });
await writeFile(`${out}/index.html`, campaignPage());
await writeFile(`${out}/.nojekyll`, '');
console.log(`Built ${out}/ with ${QUESTIONS.length} questions.`);
